import{z as i,x as s,o,c as l,q as E,j as d,D as e,d as A,s as B,S as r}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"位置无关代码","description":"","frontmatter":{"title":"位置无关代码","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pic.md","filePath":"cs/pic.md","lastUpdated":1791063341000}'),c={name:"cs/pic.md"};function n(p,a,P,T,C,h){const t=s("Mermaid");return o(),l("div",null,[a[2]||(a[2]=E('<h1 id="位置无关代码" tabindex="-1">位置无关代码 <a class="header-anchor" href="#位置无关代码" aria-label="Permalink to &quot;位置无关代码&quot;">​</a></h1><div class="epigraph"><p>指令不假设自己被装在固定虚址；对全局的访问改成 PC 相对或经 GOT 间接，同一份文本才能被映射到不同进程的不同基址。</p><footer>—— 据 System V ABI 与 ELF 规范；Levine, Linkers and Loaders, 2000 整理</footer></div><p>上一课<a href="/cs/abi-codegen">ABI 与代码生成</a>按合同发出序言、参数寄存器与 <code>jal</code>。许多立即数仍是「链接时再填的绝对地址」。本课不重写 callee-save。缺口是<strong>位置无关</strong>：共享库与 ASLR 下，代码段要可写时才重定位会失去页共享。编译器改为 PC 相对取址；对外部符号留下经 GOT 的间接。下一课链接器仍填空洞，只是空洞的类型变成相对或 GOT 槽。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定地址代码：<code>lui</code>/<code>addi</code> 拼出 <code>foo</code> 的虚址。加载到别的基址则全部重定位项要改代码页，文本不能在进程间只读共享，ASLR 每次加载都改页。PIC：对函数用相对 <code>jal</code>/<code>b</code>；对全局数据用「当前 PC 加位移」或「先找 GOT 再 load」。RISC-V 的 <code>auipc</code>+<code>addi</code>、x86-64 的 RIP-relative 即此。缺口是代码生成契约，不是再讲 ABI 寄存器号。</p><p><span class="marginnote">术语翻译：GOT（全局偏移表）像酒店前台的一块指示牌——代码只管问「<code>foo</code> 在哪」，前台按这一次加载的实际位置作答；下次换基址，改指示牌就行，不用改写任何指令。</span></p><p>静态可执行文件仍可走绝对地址，简单且快。共享对象（<code>-fPIC</code>）必须 PIC。可执行文件 PIC（PIE）为 ASLR 服务，后课安全课再收；本课钉生成侧。</p><h3 id="pic-不是「没有重定位」" tabindex="-1">PIC 不是「没有重定位」 <a class="header-anchor" href="#pic-不是「没有重定位」" aria-label="Permalink to &quot;PIC 不是「没有重定位」&quot;">​</a></h3><p>仍有重定位：相对位移、GOT 槽的运行时填充。改的是<strong>数据页</strong>（GOT），不是每条指令。不要声称 PIC 零链接。</p><p><span class="marginnote">System V ABI 描述 PIC 与 GOT。Levine 把加载与共享库写成教材。龙书第 7 章链接不把 PIC 写深，本课补在 ABI 与链接之间。<a href="/cs/aslr-nx">ASLR</a> 是安全课消费本课产物。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对局部静态：PC 相对。对外部或可被动态覆盖的符号：生成经 GOT 的 load，槽位由汇编留下重定位类型。小 PIC / 大 PIC（是否假设 GOT 近）按目标约定。禁止在 <code>.text</code> 里留下需改写的绝对立即数。</p>',12)),(o(),d(r,null,{default:e(()=>[B(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22%E7%AC%A6%E5%8F%B7%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20REL%5B%22PC%20%E7%9B%B8%E5%AF%B9%22%5D%0A%20%20SYM%20--%3E%20GOT%5B%22%E7%BB%8F%20GOT%20%E9%97%B4%E6%8E%A5%22%5D%0A%20%20REL%20--%3E%20SHARE%5B%22%E6%96%87%E6%9C%AC%E9%A1%B5%E5%8F%AA%E8%AF%BB%E5%85%B1%E4%BA%AB%22%5D%0A%20%20GOT%20--%3E%20SHARE%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>与<a href="/cs/instruction-select">指令选择</a>：<code>auipc</code> 序列是选择问题；本课规定何时必须选它们而不是绝对 <code>lui</code>。</p><p><span class="marginnote">数字实例：x86-64 的 RIP-relative 用 32 位位移，够覆盖当前 PC 前后 ±2 GiB——这就是「小 PIC」敢假设 GOT 离得近的底气；库被映射得更远时，就得换多几条指令的大模型序列。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多一份间接：调用外部可能多一次 load。热路径可用复制重定位（copy reloc）把符号搬进可执行文件，那是链接策略，点名。不要把 PIC 与无栈解释器混谈。</p>',4)),(o(),d(r,null,{default:e(()=>[B(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20ABS%5B%22%E7%BB%9D%E5%AF%B9%E5%9C%B0%E5%9D%80%E4%BB%A3%E7%A0%81%22%5D%0A%20%20%20%20A1%5B%22%E5%8A%A0%E8%BD%BD%E5%88%B0%E9%9A%8F%E6%9C%BA%E5%9F%BA%E5%9D%80%22%5D%20--%3E%20A2%5B%22%E6%94%B9%E5%86%99%E5%90%AB%E7%BB%9D%E5%AF%B9%E5%9C%B0%E5%9D%80%E7%9A%84%E4%BB%A3%E7%A0%81%E9%A1%B5%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E9%A1%B5%E5%8F%98%E8%84%8F%3A%20%E5%90%84%E8%BF%9B%E7%A8%8B%E4%B8%80%E4%BB%BD%2C%20%E5%85%B1%E4%BA%AB%E6%B3%A1%E6%B1%A4%22%5D%0A%20%20end%0A%20%20subgraph%20PICG%5B%22PIC%22%5D%0A%20%20%20%20B1%5B%22%E5%8A%A0%E8%BD%BD%E5%88%B0%E9%9A%8F%E6%9C%BA%E5%9F%BA%E5%9D%80%22%5D%20--%3E%20B2%5B%22%E5%8F%AA%E5%A1%AB%20GOT%20%E8%BF%99%E9%A1%B5%E6%95%B0%E6%8D%AE%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E4%BB%A3%E7%A0%81%E9%A1%B5%E5%8E%9F%E6%A0%B7%E5%8F%AA%E8%AF%BB%2C%20%E5%85%A8%E8%BF%9B%E7%A8%8B%E5%85%B1%E7%94%A8%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p>线程局部（TLS）另有模型，本课不展开。</p><p><span class="marginnote">常见误区：以为 PIC 等于「零重定位、零开销」——重定位还在，只是从改代码页变成填 GOT；外部符号访问也因此多一次内存 load，这是拿一跳间接换整页共享与 ASLR。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不合并节、不解析 <code>printf</code> 到 libc。不写 PLT 桩的第一条 <code>jmp *GOT</code>——下一课链接之后、再下一课 GOT/PLT 表。后课默认：共享代码按 PIC 生成。链接把相对空洞与 GOT 槽写进 ELF。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PIC 用 PC 相对或 GOT 间接，文本可共享、可滑基址。</li><li>仍有重定位，对象从代码页换成 GOT。</li><li>静态绝对代码仍合法，共享库不行。</li><li>出处：System V ABI；ELF；Levine, 2000。</li></ul>',6))])}const I=i(c,[["render",n]]);export{m as __pageData,I as default};
